function wordpressId(value, label) {
  if (!Number.isSafeInteger(value) || value < 1)
    throw new Error(label + " must be a positive WordPress ID");
  return value;
}

function articleSettings(postId, mode, voiceId, reuseMediaId) {
  wordpressId(postId, "Post ID");
  if (mode !== "summary" && mode !== "transcript") throw new Error("Choose summary or transcript");
  if (!Number.isSafeInteger(reuseMediaId) || reuseMediaId < 0)
    throw new Error("Enter an existing media ID or leave it at zero");
  if (
    !reuseMediaId &&
    (typeof voiceId !== "string" ||
      voiceId === "YOUR_ELEVENLABS_VOICE_ID" ||
      !/^[A-Za-z0-9_-]{3,80}$/.test(voiceId))
  ) {
    throw new Error("Enter your ElevenLabs voice ID");
  }
  const attachment = "article-" + postId + "-" + mode;
  return {
    postId,
    mode,
    voiceId,
    reuseMediaId,
    attachment,
    fileName: attachment + ".mp3",
    key: "wp-article-audio:" + postId,
  };
}

export default ({ postId, mode, voiceId, reuseMediaId }) => {
  const settings = articleSettings(postId, mode, voiceId, reuseMediaId);
  return { settings, postId, mediaId: reuseMediaId || 1, voiceId, postPath: "/posts/" + postId };
};

