function httpsResource(value) {
  if (
    typeof value !== "string" ||
    !/^https:\/\/[A-Za-z0-9.-]+(?::\d{1,5})?(?:[/?][^\s"'<>]*)?$/i.test(value)
  ) {
    throw new Error("WordPress media needs a valid HTTPS source URL");
  }
  return value;
}

export default async ({ file, settings }, context) => {
  if (!["audio/mpeg", "audio/mp3"].includes(file.mimetype))
    throw new Error("ElevenLabs did not return MP3 audio");
  const url = httpsResource(file.s3url);
  if (!(await context.state.insert(settings.key, { state: "pending_upload" }))) {
    throw new Error("A WordPress write for this post is already pending");
  }
  return { url, fileName: settings.fileName, slug: settings.attachment };
};

