function wordpressId(value, label) {
  if (!Number.isSafeInteger(value) || value < 1)
    throw new Error(label + " must be a positive WordPress ID");
  return value;
}

function httpsResource(value) {
  if (
    typeof value !== "string" ||
    !/^https:\/\/[A-Za-z0-9.-]+(?::\d{1,5})?(?:[/?][^\s"'<>]*)?$/i.test(value)
  ) {
    throw new Error("WordPress media needs a valid HTTPS source URL");
  }
  return value;
}

function confirmMedia(media, settings) {
  const id = wordpressId(media?.id, "Uploaded media ID");
  const sourceUrl = httpsResource(media.source_url);
  const name = sourceUrl.split("?")[0].split("/").at(-1);
  const suffix = name.slice(settings.attachment.length);
  if (
    media.post !== settings.postId ||
    !["audio/mpeg", "audio/mp3"].includes(media.mime_type) ||
    !name.startsWith(settings.attachment) ||
    !/^(?:-\d+)?\.mp3$/.test(suffix) ||
    (settings.reuseMediaId && id !== settings.reuseMediaId)
  ) {
    throw new Error("WordPress media does not match the MP3 for this post and narration mode");
  }
  return { mediaId: id, sourceUrl };
}

export default async ({ uploaded, existing, settings }, context) => {
  const media = confirmMedia(uploaded ?? existing, settings);
  await context.state.set(settings.key, { state: "pending_post_update", mediaId: media.mediaId });
  return { media };
};

